// Generated by OrchestKit Claude Plugin
// Created: 2026-11-15

/**
 * Rules hash: one sha256 over the user-level instruction files Claude Code
 * loads into a session, so every session row can name the rule version it ran
 * under (migration 006, sessions.rules_hash).
 *
 * Inputs, in this fixed order:
 *   1. <claudeDir>/CLAUDE.md
 *   2. each `@file` import line of that CLAUDE.md, in order of appearance
 *   3. <claudeDir>/rules/**\/*.md, sorted by relative path
 *   4. the active output style: settings.json `outputStyle`, matched against
 *      output-styles/*.md by frontmatter `name:` or file stem
 *
 * Every file contributes `label NUL content NUL`, so a rename changes the hash
 * as well as an edit. An empty input set is an explicit failure, never the
 * hash of nothing: a hash that every machine with no rules shares would make
 * `sessions-under` list unrelated sessions as one version.
 *
 * Read only. No network, no writes, no child process.
 */

import { createHash } from 'node:crypto';
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { isAbsolute, join, relative, resolve, sep } from 'node:path';
import { getHomeDir } from './paths.js';

/** Value stored in sessions.rules_hash when there is nothing to hash. */
export const RULES_HASH_EMPTY = 'rules_hash_empty';

export type RulesHashResult =
  | { ok: true; hash: string; files: string[] }
  | { ok: false; reason: string };

/** The Claude Code config dir: CLAUDE_CONFIG_DIR when set, else ~/.claude. */
export function resolveClaudeDir(): string {
  return process.env.CLAUDE_CONFIG_DIR || join(getHomeDir(), '.claude');
}

function isFile(p: string): boolean {
  try {
    return statSync(p).isFile();
  } catch {
    return false;
  }
}

/** `@path` import lines of a CLAUDE.md, resolved against its directory. */
function importsOf(claudeMd: string, claudeDir: string): string[] {
  const out: string[] = [];
  for (const line of readFileSync(claudeMd, 'utf8').split('\n')) {
    const m = line.trim().match(/^@(\S+)$/);
    if (!m?.[1]) continue;
    const raw = m[1];
    const p = raw.startsWith('~/') ? join(getHomeDir(), raw.slice(2)) : isAbsolute(raw) ? raw : resolve(claudeDir, raw);
    if (isFile(p)) out.push(p);
  }
  return out;
}

/** rules/**\/*.md under claudeDir, sorted by relative path (byte order). */
function ruleFiles(claudeDir: string): string[] {
  const root = join(claudeDir, 'rules');
  if (!existsSync(root)) return [];
  const found: string[] = [];
  const walk = (dir: string): void => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const p = join(dir, entry.name);
      if (entry.isDirectory()) walk(p);
      else if (entry.isFile() && entry.name.endsWith('.md')) found.push(p);
    }
  };
  walk(root);
  return found.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
}

/** The active output style name from settings.json, or null when none is set. */
function activeOutputStyle(claudeDir: string): string | null {
  const settings = join(claudeDir, 'settings.json');
  if (!isFile(settings)) return null;
  try {
    const parsed = JSON.parse(readFileSync(settings, 'utf8')) as { outputStyle?: unknown };
    return typeof parsed.outputStyle === 'string' && parsed.outputStyle.trim() ? parsed.outputStyle.trim() : null;
  } catch {
    return null;
  }
}

/** output-styles/*.md whose frontmatter name or file stem matches `name`. */
function outputStyleFile(claudeDir: string, name: string): string | null {
  const dir = join(claudeDir, 'output-styles');
  if (!existsSync(dir)) return null;
  const want = name.toLowerCase();
  const files = readdirSync(dir).filter(f => f.endsWith('.md')).sort();
  for (const f of files) {
    const p = join(dir, f);
    const head = readFileSync(p, 'utf8').split('\n').slice(0, 20);
    const nameLine = head.find(l => /^name:\s*/.test(l));
    const fmName = nameLine ? nameLine.replace(/^name:\s*/, '').trim().replace(/^["']|["']$/g, '') : '';
    if (fmName.toLowerCase() === want || f.slice(0, -3).toLowerCase() === want) return p;
  }
  return null;
}

/** Label a file by its path under claudeDir, or absolute when outside it. */
function labelOf(p: string, claudeDir: string): string {
  const rel = relative(claudeDir, p);
  return rel.startsWith('..') || isAbsolute(rel) ? p : rel.split(sep).join('/');
}

/**
 * Hash the rule files under `claudeDir`. Pass a temp copy to probe it; the
 * function never writes, so pointing it at the live ~/.claude is safe.
 */
export function computeRulesHash(claudeDir: string = resolveClaudeDir()): RulesHashResult {
  try {
    const ordered: string[] = [];
    const seen = new Set<string>();
    const add = (p: string): void => {
      if (!seen.has(p)) {
        seen.add(p);
        ordered.push(p);
      }
    };

    const claudeMd = join(claudeDir, 'CLAUDE.md');
    if (isFile(claudeMd)) {
      add(claudeMd);
      for (const p of importsOf(claudeMd, claudeDir)) add(p);
    }
    for (const p of ruleFiles(claudeDir)) add(p);

    const style = activeOutputStyle(claudeDir);
    const styleFile = style ? outputStyleFile(claudeDir, style) : null;
    if (styleFile) add(styleFile);

    if (ordered.length === 0 && !style) {
      return { ok: false, reason: `no CLAUDE.md, rules/*.md or output style under ${claudeDir}` };
    }

    const h = createHash('sha256');
    const labels: string[] = [];
    for (const p of ordered) {
      const label = labelOf(p, claudeDir);
      labels.push(label);
      h.update(label).update('\0').update(readFileSync(p)).update('\0');
    }
    // A selected style with no file still names the selection, so switching
    // styles changes the hash even when the style comes from elsewhere.
    if (style && !styleFile) {
      const label = `output-style:${style}:unresolved`;
      labels.push(label);
      h.update(label).update('\0');
    }
    return { ok: true, hash: h.digest('hex'), files: labels };
  } catch (err) {
    return { ok: false, reason: `rules hash read failed: ${(err as Error).message}` };
  }
}
